utton type="button" class="row setting-toggle" data-setting-toggle="grid"><span class="row-text"><b>grid background</b><small>show the faint grid behind pages</small></span><span class="switch"><i></i></span></button> <button type="button" class="row setting-toggle" data-setting-toggle="translate"><span class="row-text"><b>translate pages</b><small>sites in another language are translated into yours, through the proxy</small></span><span class="switch"><i></i></span></button> <button type="button" class="row setting-toggle" data-setting-toggle="compact"><span class="row-text"><b>compact toolbar</b><small>tighter tabs and address bar</small></span><span class="switch"><i></i></span></button> </div> <div class="group"> <div class="group-title">search</div> <div class="row select-row"><div class="row-text"><b>search engine</b><small>used when you type plain text</small></div> <select id="search-engine-setting" aria-label="search engine"> <option value="duckduckgo">duckduckgo</option> <option value="google">google</option> <option value="bing">bing</option> <option value="brave">brave</option> </select></div> <div class="row select-row"><div class="row-text"><b>proxy</b><small>switching reloads mochii</small></div> <select id="proxy-setting" aria-label="proxy"> <option value="ssj">src@mj3t</option> <option value="uvt">u1tr@v</option> </select></div> <div class="row select-row"><div class="row-text"><b>transport</b><small>epoxy is encrypted, libcurl is the fallback. switching reloads mochii</small></div> <select id="transport-setting" aria-label="transport"> <option value="epoxy">epoxy</option> <option value="libcurl">libcurl</option> </select></div> <div class="row"><div class="row-text"><b>search history</b><small>recent searches shown in suggestions</small></div> <button class="btn" id="clear-history" type="button">clear</button></div> </div> <div class="group"> <div class="group-title"><span>blocked</span><button class="btn" id="reset-block-stats" type="button">reset</button></div> <div class="block-stats" id="block-stats"></div> <button type="button" class="row setting-toggle" data-setting-toggle="blockStats"><span class="row-text"><b>show on home</b><small>the ads and trackers count under your bookmarks</small></span><span class="switch"><i></i></span></button> </div> <div class="group"> <div class="group-title">proxy server</div> <div class="server-list" id="server-list"></div> <div class="custom-input-group"> <input type="text" id="custom-wisp-input" placeholder="wss://your-server.com/api/" spellcheck="false" aria-label="custom server url"> <button class="btn primary" id="save-custom-wisp" type="button">add server</button> </div> </div> <div class="group"> <div class="row"><div class="row-text"><b>reset to defaults</b><small>restores preferences, theme and wallpaper. proxy servers are kept.</small></div> <button class="btn" id="reset-settings" type="button">reset</button></div> </div> </section> <section class="settings-pane hidden" data-settings-pane="appearance"> <div class="settings-pane-title">appearance</div> <div class="group"> <div class="group-title"><span>theme</span><span id="settings-theme-name">default</span></div> <div class="theme-list" id="theme-list"></div> </div> <div class="group"> <div class="group-title">home</div> <div class="row"><div class="row-text"><b>home page</b><small>what goes above the search bar</small></div> <div class="seg" role="group" aria-label="home page"> <button type="button" data-setting-select="homeHero" data-value="name">name</button> <button type="button" data-setting-select="homeHero" data-value="clock">clock</button> </div></div> </div> <div class="group"> <div class="group-title">font</div> <div class="row select-row"><div class="row-text"><b>site font</b><small>does not change the websites you browse</small></div> <select id="font-setting" aria-label="site font"></select></div> </div> <div class="group"> <div class="group-title"><span>wallpaper</span><button class="btn" id="wallpaper-refresh-btn" type="button">refresh</button></div> <div class="wallpaper-grid" id="wallpaper-grid"></div> <div class="row"> <div class="row-text"><b>your own image</b><small id="background-name">no background selected</small></div> <div class="background-actions"> <button class="btn background-btn remove" id="background-remove-btn" type="button">remove</button> <button class="btn background-btn" id="background-upload-btn" type="button">upload</button> </div> <input id="background-file-input" type="file" accept="image/*" hidden> </div> </div> </section> <section class="settings-pane hidden" data-settings-pane="anime"> <div class="settings-pane-title">anime</div> <div class="group"> <div class="group-title">player</div> <div class="row"><div class="row-text"><b>audio</b><small>subbed or dubbed, when an episode has both</small></div> <div class="seg" role="group" aria-label="audio"> <button type="button" data-anime-select="lang" data-value="sub">sub</button> <button type="button" data-anime-select="lang" data-value="dub">dub</button> </div></div> <div class="row select-row"><div class="row-text"><b>speed</b><small>what episodes play at</small></div> <select id="anime-speed-setting" aria-label="playback speed"> <option value="0.5">0.5×</option><option value="0.75">0.75×</option><option value="1">normal</option><option value="1.25">1.25×</option> <option value="1.5">1.5×</option><option value="1.75">1.75×</option><option value="2">2×</option> </select></div> <button type="button" class="row setting-toggle" data-anime-toggle="auto"><span class="row-text"><b>autoplay next episode</b><small>starts the next one when an episode ends</small></span><span class="switch"><i></i></span></button> <button type="button" class="row setting-toggle" data-anime-toggle="skip"><span class="row-text"><b>skip intros</b><small>jumps past the opening when mochii knows where it ends</small></span><span class="switch"><i></i></span></button> <button type="button" class="row setting-toggle"