const qe="mochii",je="2.16",Ue=[{v:"2.16",items:["chat cosmetics shop: avatar decorations, profile effects and nameplates for mochis, with a weekly featured drop. open it with /shop or the bag button","chat messages support markdown: *italic*, __underline__, ~~strike~~, ||spoilers||, > quotes, # headers, lists, code blocks and [masked](links)","command animations: coinflips spin, dice tumble, slots reels roll and battles play out before the result shows","new commands: /ask (ai), /slots, /heist, /lottery, /gift, /8ball, /ship, /rate, /marry, /divorce and /rep","battles no longer get stuck after accepting, and ones nobody finishes time out after 10 minutes"]},{v:"2.15",items:["new manga page: search and read manga, manhwa and manhua in mochii's own reader, licensed ones too, with your place in each one saved","new live tv page: free news, sports, movie and music channels from around the world, through the proxy. it opens on popular channels: espn, fox sports 1, nba tv, comedy central, bbc earth, cnn and more"]},{v:"2.14",items:["the chat members list updates live: people show as online or offline within a couple of seconds, and activity changes show straight away","the chat header shows how many people are online right now"]},{v:"2.13",items:["youtube loads again on the newest chrome, safari and firefox (it was failing on every server with an http2 error)"]},{v:"2.12",items:["games run smoother: the wallpaper shader and the game list stop drawing while a game is open, so the game gets the whole gpu"]},{v:"2.12",items:["games run smoother: the wallpaper shader pauses while a game is open, and game frames are paced to a steady 60fps even on 120hz screens"]},{v:"2.11",items:["chat messages, typing and voice now arrive instantly over a live connection instead of being checked every 2 seconds","accounts, chat and storage go through mochii's own server, so the database address is never visible in the browser","you will need to sign in again once"]},{v:"2.10",items:["wallpaper shaders follow your cursor, over pages and sites too","youtube always goes through the zaka server first, whatever server the rest of the site is on","new default bookmarks: youtube, discord, tiktok, atsu and letterboxd"]},{v:"2.9",items:["auto translate: sites in another language are translated into yours as they load, through the proxy. the chip in the address bar shows the original","turn it off in settings, general, if you'd rather read sites as they are","search suggestions and the extension store's pictures load through the proxy too","files you download from sites keep their real names"]},{v:"2.8",items:["if a server stops answering, each request and connection moves on to the next server by itself. only when all of them fail do you get the error page","ambient light for youtube is in the extension marketplace: a soft glow of the video's colors around the player","extension fixes: vimium and other extensions whose scripts share globals work on sites now","clicking an extension's button while its popup is open closes it, and switching popups no longer opens one off screen","extension right click menus and alarms stay after a reload, and their names show translated","fixes for extension messages sent right after connecting, settings saved at startup, toolbar icons and stylus's popup data","ad blocking rules no longer block a whole site you open yourself unless the rule is meant to"]},{v:"2.7",items:["animated wallpapers: ascii and ink now move, and there are four new ones: aurora, contour, dots and threads","they pause while a site is open or mochii is in the background, and stay still if your system asks for less motion"]},{v:"2.6",items:["a new look: tabs along the top, a full width address bar and a sidebar with all of mochii's pages","mochii's own pages show up as mochii://home, mochii://games and so on. type one into the address bar to jump there","your account picture sits next to the address bar, and what's new is in settings, under about","new wallpapers: ascii (the new default) and smoke. the halloween theme and wallpaper are gone","the tabs, address bar and sidebar are a little see-through, so your wallpaper shows behind them","anime settings: pick sub or dub, the speed, autoplay, intro skipping and subtitles in settings","each page gets one tab: clicking games when it's already open takes you back to that tab. searches from home open in a new tab","home widgets and the most played games list are gone, settings is tidier, and everything is a little smaller","the anime airing tab is a timeline: pick a day, from two days ago to a week ahead, and see what airs when","girls' last tour and lucky star wallpapers","the shows page loads its movies, search and posters through the proxy, so it works where those sites are blocked"]},{v:"2.5",items:["home widgets: continue watching, recently played, recent music, weather, notes and a to-do list. turn them on in settings, appearance","a status page in settings that shows which servers are up and how fast they are","keyboard shortcuts: press ? to see them all, alt t / alt w for tabs","anime and music no longer hang when a proxy server stops working. mochii now checks that a server really works and moves to one that does","a proper error page with retry and switch server when a site won't load","loading placeholders on the anime, shows and games pages"]}],ze="/p/chatrooms.html",Be=(()=>{if(!window.__legalHtml)return{terms:"/legal/terms.html",privacy:"/legal/privacy.html"};const e=URL.createObjectURL(new Blob([window.__legalHtml],{type:"text/html"}));return{terms:e+"#terms",privacy:e+"#privacy"}})(),Le="home",Re="https://discord.gg/cmzz7cRqaH",He="mochii.chat",De=["games","chat"],Je=[{id:"openai/gpt-oss-120b",label:"gpt-oss 120b",group:"groq",tools:!0},{id:"openai/gpt-oss-20b",label:"gpt-oss 20b",group:"groq",tools:!0},{id:"qwen/qwen3.8-27b",label:"qwen 3.8 27b",group:"groq"},{id:"openrouter/free",label:"auto (best free)",group:"openrouter free",vision:!0},{id:"google/gemma