er-events:none;\n      background:radial-gradient(closest-side,var(--accent-soft),transparent);filter:blur(10px);opacity:.9}\n    .g-title{font-size:clamp(30px,5vw,44px);font-weight:600;letter-spacing:-.03em;color:var(--text-white);line-height:1.05}\n    .g-sub{margin-top:8px;font-size:13px;color:var(--text-muted)}\n    .g-sub b{color:var(--text-secondary);font-weight:500}\n    .tools{max-width:600px;margin:22px auto 0}\n    .g-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin:14px auto 0}\n    .chip{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 13px;border-radius:99px;font-size:12.5px;color:var(--text-muted);\n      background:var(--surface-2);border:1px solid var(--border-subtle);transition:background .15s,color .15s,border-color .15s,transform .15s}\n    .chip:hover{color:var(--text-white);border-color:var(--border-faint)}\n    .chip:active{transform:scale(.96)}\n    .chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent,#fff)}\n    .chip small{font-size:11px;opacity:.6}\n    .chip svg{flex:0 0 auto}\n    .chip.dice{color:var(--text-secondary)}\n    .chip.dice:hover svg{transform:rotate(-20deg) scale(1.1)}\n    .chip.dice svg{transition:transform .2s}\n    .status{text-align:center;margin-top:10px}\n    .g-sec{display:flex;align-items:baseline;gap:8px;margin:30px 2px 12px;font-size:15px;font-weight:550;color:var(--text-white);letter-spacing:-.01em}\n    .g-sec small{font-size:12px;font-weight:400;color:var(--text-faint)}\n    .g-sec button{margin-left:auto;font-size:12px;color:var(--text-faint);transition:color .12s}\n    .g-sec button:hover{color:var(--text-white)}\n    .shelf{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(150px,170px);gap:14px;overflow-x:auto;padding:4px 2px 14px;margin:0 -2px;scroll-snap-type:x proximity;scrollbar-width:thin}\n    .shelf .card{scroll-snap-align:start;aspect-ratio:1/1}\n    .grid{gap:14px}\n    .games-grid{grid-template-columns:repeat(auto-fil